body {
  padding: 0;
  margin: 0;
}

/* .ant-col {border:1px solid #eee;} */
.syntax-highlighter {
  word-break: break-all;
}

pre {
  word-wrap: break-word
}

.demo-wrapper {
  display: flex;
  align-items: center;
  justify-items: center;
  flex-direction: column;
  padding: 0 5%;
  margin-bottom: 72px;
}

.global-operation{
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 12px;
}

.global-var{
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 12px;
}

.rtm-config-wrapper{
  display: flex;
  flex-direction: column;
  width: 100%;
}

.ant-row{
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 4px;
}

.ant-form-item{
  margin: 0;
}

span span {
  color: gray;
  font-weight: 700;
}

.ant-row .ant-input-disabled {
  color: red;
}

.ant-row .color-black {
  color: black;
}

.label-red label{
  color: red !important;
}

.ant-row .color-info {
  color: #1677ff;
}
